<script>
 
 let {src=''}=$props();let canvas=$state();
 $effect(()=>{if(!src||!canvas)return;const im=new Image();im.src=src;let alive=true,idle;im.onload=()=>{const render=()=>{if(!alive)return;const work=document.createElement('canvas');work.width=256;work.height=160;const c=work.getContext('2d',{willReadFrequently:true});c.drawImage(im,0,0,256,160);const pixels=c.getImageData(0,0,256,160).data;const bins=Array.from({length:3},()=>Array(128).fill(0));for(let i=0;i<pixels.length;i+=4)for(let k=0;k<3;k++)bins[k][pixels[i+k]>>1]++;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,256,90);const max=Math.max(...bins.flat());['#c5555c','#639776','#688fae'].forEach((color,k)=>{ctx.beginPath();ctx.moveTo(0,90);bins[k].forEach((v,i)=>ctx.lineTo(i*2,90-Math.sqrt(v/max)*83));ctx.lineTo(256,90);ctx.closePath();ctx.fillStyle=color+'70';ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=1;ctx.stroke();});};idle=window.requestIdleCallback?requestIdleCallback(render,{timeout:700}):setTimeout(render,120);};return()=>{alive=false;im.onload=null;if(window.cancelIdleCallback)cancelIdleCallback(idle);else clearTimeout(idle);};});
</script>
<canvas bind:this={canvas} width="256" height="90" aria-label="颜色分布图"></canvas>
